const assert=require('node:assert/strict')
const fs=require('node:fs')
const read=p=>fs.readFileSync(p,'utf8')
const sql=read('supabase/migrations/20261027170000_conferencia_independente_wvetro_atlas_pagamentos_v1.sql')
const route=read('app/api/vendas/conferencia-importacao/route.ts')
const ui=read('components/clientes/VendaConferenciaImportacao.tsx')
const cmv=read('components/clientes/VendaCmvPainel.tsx')
const central=read('components/clientes/VendaObraCentral.tsx')
for(const s of ['wvetro_venda','atlas_venda','wvetro_pagamento'])assert.match(sql,new RegExp(s))
assert.match(sql,/enable row level security/i)
assert.match(sql,/financeiro.*cliente_id=v_venda\.cliente_id|cliente_id=v_venda\.cliente_id/)
assert.match(sql,/and tipo_titulo='R' and status_vinculo='seguro'/)
assert.match(sql,/lower\(role\)='master'/)
assert.match(sql,/valor_anterior,valor_conferido,justificativa/)
assert.match(sql,/p_valor_anterior is null or round\(p_valor_anterior,2\)<>v_atual/)
assert.match(sql,/p_tipo='atlas_venda' and p_acao<>'validado'/)
assert.doesNotMatch(sql,/update public\.(?:financeiro_contas_receber|wvetro_historico_financeiro|vendas_obras|wvetro_orcamentos_historico)/i)
assert.match(route,/eq\('cliente_id',venda.cliente_id\)/)
assert.match(route,/eq\('orcamento_wvetro',numero\)/)
assert.match(route,/eq\('tipo_titulo','R'\)/)
assert.match(route,/eq\('status_vinculo','seguro'\)/)
assert.match(route,/Conferência financeira disponível apenas para Master/)
assert.match(route,/VERCEL_ENV==='preview'/)
assert.match(route,/private, no-store/)
assert.match(ui,/Valor importado do W.Vetro/)
assert.match(ui,/Valor da venda no Atlas/)
assert.match(ui,/Validar/)
assert.match(ui,/Corrigir/)
assert.match(ui,/valorWvetroOriginal/)
assert.match(ui,/valorWvetroConferido/)
assert.match(ui,/valorAtlas/)
assert.match(ui,/botoes\('wvetro_venda'/)
assert.match(ui,/botoes\('atlas_venda'/)
assert.match(ui,/botoes\('wvetro_pagamento'/)
assert.match(ui,/Editar pagamento Atlas/)
assert.match(ui,/corrigirPagamentoAtlas/)
assert.match(ui,/acao:'corrigido'/)
assert.match(ui,/ajustarParcela:ajustarParcela&&numeroTitulos>0/)
assert.match(ui,/não cria recebimentos nem baixa parcelas/)
assert.doesNotMatch(ui,/Registrar valor já pago/)
assert.match(cmv,/VendaConferenciaImportacao/)
assert.doesNotMatch(central,/onRegistrarRecebimento=\{\(\)=>setModalRecebimento\(true\)\}/)
console.log('PASS: W.Vetro e Atlas independentes, pagamentos importados auditados sem baixa, Master, tenant, histórico e preservação do financeiro legado.')
